import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"第二册：实践与进步 · Lesson 46 Expensive and uncomfortable","description":"学习 数量表达与范围，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 46 Expensive and uncomfortable","description":"学习 数量表达与范围，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 数量表达与范围，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 45 A clear conscience","link":"/life/english/new-concept/book-2/unit-02/lesson-045"},"next":{"text":"第二册：实践与进步 · Lesson 47 A thirsty ghost","link":"/life/english/new-concept/book-2/unit-02/lesson-047"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 45 A clear conscience","link":"/life/english/new-concept/book-2/unit-02/lesson-045"},"next":{"text":"第二册：实践与进步 · Lesson 47 A thirsty ghost","link":"/life/english/new-concept/book-2/unit-02/lesson-047"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-046.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-046.md"}'),r={name:"life/english/new-concept/book-2/unit-02/lesson-046.md"};function s(i,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-46-expensive-and-uncomfortable" tabindex="-1">第二册：实践与进步 · Lesson 46 Expensive and uncomfortable <a class="header-anchor" href="#第二册-实践与进步-·-lesson-46-expensive-and-uncomfortable" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 46 Expensive and uncomfortable&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>昂贵旅程未必带来舒适体验，费用与感受需要分别比较；练习数量表达和比较对象。本课的语言观察是：less comfortable 比较舒适程度，more money 比较不可数的费用。fewer 只适合可数复数，如 fewer seats，不能说 fewer money。完成学习后，请比较两种交通选择，写费用、座位和最终决定。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>cost</td><td>/kɒst/</td><td>n.</td><td>费用</td><td>the total cost</td></tr><tr><td>comfortable</td><td>/ˈkʌmftəbəl/</td><td>adj.</td><td>舒适的</td><td>a comfortable chair</td></tr><tr><td>expensive</td><td>/ɪkˈspensɪv/</td><td>adj.</td><td>昂贵的</td><td>an expensive mistake</td></tr><tr><td>afford</td><td>/əˈfɔːd/</td><td>v.</td><td>负担得起</td><td>afford a holiday</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>spend money on — 在……上花钱</li><li>be worth the cost — 值得这个价钱</li></ul><h2 id="语法讲解-数量表达与范围" tabindex="-1">语法讲解：数量表达与范围 <a class="header-anchor" href="#语法讲解-数量表达与范围" aria-label="Permalink to &quot;语法讲解：数量表达与范围&quot;">​</a></h2><p>many、few 修饰可数复数，much、little 修饰不可数名词；a few 和 a little 强调有一些，few 和 little 往往强调不足。all、both、each、every 的范围不同，谓语单复数要看实际主语而不是最近的名词。数量比较中的 more、less、fewer 也需结合可数性。表述统计或费用时要给出单位和参照范围，避免只有数字却没有明确对象。本课应用：less comfortable 比较舒适程度，more money 比较不可数的费用。fewer 只适合可数复数，如 fewer seats，不能说 fewer money。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The overnight train cost more but offered fewer comfortable seats.</p></blockquote><p>夜间列车更贵，却提供了更少的舒适座位。</p><p>cost 是过去式，与原形同形；more 省略比较中的 money，fewer 修饰可数复数 seats。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>fewer comfort 不对，comfort 通常不可数；可说 less comfort 或 fewer comfortable seats。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照 cheaper 与 fewer 的末尾弱音；重读 but 突出价格与体验不一致。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The overnight train cost more but offered fewer comfortable seats. We changed to a daytime service on the return trip. It was cheaper and gave us a better view.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>比较两种交通选择，写费用、座位和最终决定。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：cost 是过去式，与原形同形；more 省略比较中的 money，fewer 修饰可数复数 seats。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：fewer comfort 不对，comfort 通常不可数；可说 less comfort 或 fewer comfortable seats。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 less/fewer：The carriage had ___ seats.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> fewer</p><p><strong>解析：</strong> seats 是可数复数名词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>回程选择了什么服务？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> A daytime train service.</p><p><strong>解析：</strong> changed to 表明改乘日间班次。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>纠正：We spent fewer money on the return trip。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We spent less money on the return trip.</p><p><strong>解析：</strong> money 不可数，用 less。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：数量表达与范围。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-045">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-047">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=t(r,[["render",s]]);export{f as __pageData,u as default};
